\set ON_ERROR_STOP on
begin;
do $$declare x jsonb;c jsonb;p jsonb;a jsonb;b jsonb;g numeric;k numeric;stock numeric;f uuid;begin
 if current_database()<>'factory_lean_quality_local' or inet_server_addr()<>'127.0.0.1'::inet then raise exception 'Local fixture required';end if;
 select t.x into x from local_preview.context t;f:=(x->>'factory')::uuid;
 perform set_config('request.jwt.claim.sub',x->>'owner',true);
 c:=public.production_correction_context(f,(x->>'entry')::uuid);
 if c->>'good' is null or c->>'unfinished' is null or c->>'remaining_work' is null or c->>'startup_kg' is null then raise exception 'Incomplete draft context';end if;
 if jsonb_typeof(c->'good')<>'string' or c->>'factory_id'<>f::text then raise exception 'Context precision/scope';end if;
 raise notice 'PASS exact complete context with immutable revision';
 select on_hand into stock from public.finished_goods_balances where factory_id=f and product_id=(c->>'product_id')::uuid and unit=c->>'unit';
 p:=jsonb_build_object('entry',c->>'id','expected_revision',(c->>'correction_revision')::integer,'good',c->>'good','discarded_quantity',c->>'discarded_quantity','scrap_kg','0.1234567890123456789','startup_kg',c->>'startup_kg','unfinished',c->>'unfinished','remaining_work',c->>'remaining_work','reason','Measurement error, checked exact weight','allocations','[]'::jsonb);
 perform set_config('request.jwt.claim.sub',x->>'worker',true);
 a:=public.production_correction_command(f,'submit',p,gen_random_uuid());b:=public.production_correction_command(f,'submit',p,gen_random_uuid());
 if a->>'status'<>'PENDING' or public.production_correction_context(f,(c->>'id')::uuid)->>'scrap_kg'<>c->>'scrap_kg' then raise exception 'Pending changed official';end if;
 raise notice 'PASS technician pending preserves official values';
 perform set_config('request.jwt.claim.sub',x->>'owner',true);
 perform public.production_correction_command(f,'approve',jsonb_build_object('id',a->>'id'),gen_random_uuid());
 if public.production_correction_context(f,(c->>'id')::uuid)->>'scrap_kg'<>'0.1234567890123456789' then raise exception 'Approval precision';end if;
 raise notice 'PASS authorized approval updates exact official Scrap';
 begin perform public.production_correction_command(f,'approve',jsonb_build_object('id',b->>'id'),gen_random_uuid());raise exception 'Missing stale denial';exception when serialization_failure then raise notice 'PASS stale proposal denied';end;
 perform public.production_correction_command(f,'reject',jsonb_build_object('id',b->>'id','reason','Review the latest measured values'),gen_random_uuid());
 raise notice 'PASS stale pending request can be rejected without posting';
 c:=public.production_correction_context(f,(c->>'id')::uuid);
 p:=p||jsonb_build_object('expected_revision',(c->>'correction_revision')::integer,'scrap_kg','0.2');
 a:=public.production_correction_command(f,'submit',p,gen_random_uuid());
 if a->>'status'<>'APPROVED' or a->>'requested_by'<>a->>'reviewed_by' then raise exception 'Self approval';end if;
 if (select on_hand from public.finished_goods_balances where factory_id=f and product_id=(c->>'product_id')::uuid and unit=c->>'unit')<>stock then raise exception 'Unexpected inventory posting';end if;
 raise notice 'PASS self approval, unchanged Good stock and WIP';
 delete from public.user_permissions where factory_id=f and user_id=(x->>'worker')::uuid and module='orders' and action='edit';
 perform set_config('request.jwt.claim.sub',x->>'worker',true);
 begin perform public.production_correction_context(f,(c->>'id')::uuid);raise exception 'Missing revocation denial';exception when insufficient_privilege then raise notice 'PASS revoked edit authority denied';end;
 perform set_config('request.jwt.claim.sub',x->>'owner',true);
 begin perform public.production_correction_context(gen_random_uuid(),(c->>'id')::uuid);raise exception 'Missing tenant denial';exception when insufficient_privilege then raise notice 'PASS foreign factory denied';end;
 if has_function_privilege('anon','public.production_correction_context(uuid,uuid)','execute') then raise exception 'Anon exposure';end if;
 raise notice 'PASS anonymous context execution revoked';
 if exists(select 1 from private.production_recording_v3_activation where enabled) then raise exception 'Activation';end if;
end$$;
rollback;
